:root{--ctbg:#070a12;--ctpanel:rgba(16,20,35,.88);--ctline:rgba(255,255,255,.09);--ctmuted:#9aa4b8;--ctaccent:#7c5cff;--ctcyan:#39d8ff;--ctgood:#57e2ad;--ctdanger:#ff6b86}.ct{min-height:100vh;padding:24px;max-width:1500px;margin:auto}.ct-head{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:20px}.ct-brand{display:flex;align-items:center;gap:12px}.ct-orb{width:44px;height:44px;border-radius:14px;display:grid;place-items:center;background:radial-gradient(circle at 30% 25%,#e9e5ff,#7c5cff 45%,#26184f);box-shadow:0 0 40px rgba(126,91,255,.28)}.ct-head h1{margin:0;font-size:29px;letter-spacing:-.04em}.ct-head p{margin:4px 0 0;color:var(--ctmuted)}.ct-back,.ct-btn{color:#fff;text-decoration:none;padding:10px 14px;border:1px solid var(--ctline);border-radius:12px;background:rgba(255,255,255,.04);cursor:pointer}.ct-btn.primary{background:linear-gradient(135deg,#7359e8,#3f8cff);border-color:transparent}.ct-hero{padding:22px;border:1px solid var(--ctline);border-radius:22px;background:linear-gradient(135deg,rgba(23,25,49,.92),rgba(10,13,25,.9));box-shadow:0 20px 60px rgba(0,0,0,.2);margin-bottom:18px}.ct-hero h2{font-size:24px;margin:0 0 7px}.ct-hero p{max-width:900px;color:var(--ctmuted);line-height:1.55;margin:0}.ct-status{display:inline-flex;align-items:center;gap:8px;margin-top:13px;padding:7px 10px;border-radius:999px;background:rgba(87,226,173,.08);color:var(--ctgood);font-size:12px}.ct-status i{width:7px;height:7px;border-radius:50%;background:currentColor;box-shadow:0 0 12px currentColor}.ct-workspace{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(300px,.75fr);gap:18px;margin-bottom:18px}.ct-stage,.ct-side,.ct-card{border:1px solid var(--ctline);border-radius:20px;background:var(--ctpanel);box-shadow:0 15px 50px rgba(0,0,0,.16)}.ct-stage{padding:16px}.ct-stage-head,.ct-side-head{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:12px}.ct-stage-head h3,.ct-side-head h3{margin:0;font-size:15px}.ct-stage-head small,.ct-side-head small{color:var(--ctmuted)}.ct-screen{position:relative;aspect-ratio:16/9;border-radius:15px;overflow:hidden;background:radial-gradient(circle at 50% 40%,#1c2440,#090c15 70%);border:1px solid var(--ctline);display:grid;place-items:center}.ct-screen video{width:100%;height:100%;object-fit:contain;display:none}.ct-screen.demo video{display:block}.ct-screen.blurred video{filter:blur(18px)}.ct-placeholder{text-align:center;color:var(--ctmuted);padding:25px}.ct-placeholder b{display:block;color:#fff;font-size:18px;margin-bottom:6px}.ct-screen.demo .ct-placeholder{display:none}.ct-live-badge{position:absolute;left:12px;top:12px;z-index:2;padding:6px 9px;border-radius:999px;background:rgba(255,50,80,.9);font-size:11px;display:none}.ct-screen.demo .ct-live-badge{display:block}.ct-chat-overlay{position:absolute;right:12px;bottom:12px;width:min(42%,280px);display:none;gap:6px;flex-direction:column;align-items:flex-end;z-index:3}.ct-screen.chat-on .ct-chat-overlay{display:flex}.ct-msg{background:rgba(5,8,16,.76);backdrop-filter:blur(10px);border:1px solid rgba(255,255,255,.1);padding:7px 9px;border-radius:10px;font-size:11px;max-width:100%}.ct-donate{position:absolute;left:12px;bottom:12px;z-index:3;padding:9px 12px;border-radius:12px;background:linear-gradient(135deg,#f0a84b,#ef4f7a);font-size:12px;display:none}.ct-screen.alert .ct-donate{display:block}.ct-controls{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.ct-side{padding:16px}.ct-side textarea,.ct-side input,.ct-card textarea{width:100%;box-sizing:border-box;border:1px solid var(--ctline);background:#0b0f1b;color:#fff;border-radius:12px;padding:10px 11px;outline:none;resize:vertical}.ct-side textarea{min-height:88px}.ct-result{margin-top:10px;padding:11px;border:1px solid var(--ctline);border-radius:12px;color:#dbe2f0;white-space:pre-wrap;font-size:12px;line-height:1.5;min-height:45px}.ct-tools{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.ct-card{padding:17px;min-height:180px;display:flex;flex-direction:column}.ct-icon{width:40px;height:40px;border-radius:12px;display:grid;place-items:center;background:rgba(124,92,255,.1);font-size:19px;margin-bottom:12px}.ct-card h3{margin:0 0 5px;font-size:15px}.ct-card p{margin:0;color:var(--ctmuted);font-size:12px;line-height:1.5;flex:1}.ct-actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}.ct-mini{padding:7px 9px;border-radius:9px;border:1px solid var(--ctline);background:rgba(255,255,255,.035);color:#fff;cursor:pointer;font-size:11px}.ct-mini.on{border-color:rgba(87,226,173,.45);color:var(--ctgood)}.ct-note{margin-top:17px;padding:13px 15px;border:1px dashed rgba(124,92,255,.32);border-radius:15px;color:var(--ctmuted);font-size:11px;line-height:1.5}.ct-log{margin-top:17px;border:1px solid var(--ctline);border-radius:15px;padding:12px;background:#080b13}.ct-log-head{display:flex;justify-content:space-between;color:var(--ctmuted);font-size:11px;margin-bottom:8px}.ct-log-body{max-height:150px;overflow:auto;font:11px/1.5 ui-monospace,monospace;color:#b9c3d8}.ct-log-body div{padding:2px 0}.good{color:var(--ctgood)}@media(max-width:1000px){.ct-tools{grid-template-columns:repeat(2,minmax(0,1fr))}.ct-workspace{grid-template-columns:1fr}}@media(max-width:620px){.ct{padding:15px}.ct-head h1{font-size:23px}.ct-tools{grid-template-columns:1fr}.ct-hero{padding:18px}.ct-screen{aspect-ratio:16/10}}
</style></head>
<body class="dashboard-page"><div class="dashboard-ambient ambient-a"></div><div class="dashboard-ambient ambient-b"></div>
<main class="ct">
<header class="ct-head"><div class="ct-brand"><div class="ct-orb">✦</div><div><h1>Creator Tools</h1><p>Evruni AI tools for streamers</p></div></div><a class="ct-back" href="/">← Evruni</a></header>
<section class="ct-hero"><div class="eyebrow">EVRUNI CREATOR</div><h2>Всё нужное для стрима — в одном лёгком пульте</h2><p>AI запускается только по действию. Демонстрация экрана и оверлеи работают прямо в браузере, а AI-инструменты вызываются по событию. Никакого постоянного анализа видео или чата.</p><span class="ct-status"><i></i> Lightweight / event-driven</span></section>
<section class="ct-workspace">
<div class="ct-stage"><div class="ct-stage-head"><div><h3>🖥️ Демонстрация экрана</h3><small>Локально в браузере — поток не отправляется на сервер</small></div><button class="ct-btn primary" id="shareBtn">Начать демонстрацию</button></div>
<div class="ct-screen" id="screen"><span class="ct-live-badge">● LIVE PREVIEW</span><video id="screenVideo" autoplay muted playsinline></video><div class="ct-placeholder"><b>Экран стрима</b>Нажми «Начать демонстрацию», чтобы показать окно, вкладку или весь экран.</div><div class="ct-chat-overlay" id="chatOverlay"><div class="ct-msg">👤 Зритель: Привет, Evruni!</div><div class="ct-msg">🔥 Зритель: Крутой момент!</div><div class="ct-msg">💬 Зритель: Когда следующий стрим?</div></div><div class="ct-donate" id="donateBadge">💰 Донат +500 ₽ · Спасибо!</div></div>
<div class="ct-controls"><button class="ct-mini" id="blurBtn">🔞 Цензура / Blur</button><button class="ct-mini" id="overlayBtn">🎨 Чат Overlay</button><button class="ct-mini" id="alertBtn">🔔 Тест доната</button><button class="ct-mini" id="stopBtn">⏹ Остановить</button></div></div>
<aside class="ct-side"><div class="ct-side-head"><div><h3>⚡ Event Console</h3><small>Действия только по событию</small></div><span class="good">● ready</span></div><textarea id="eventText" placeholder="Например: зритель написал «Как настроить OBS?»"></textarea><div class="ct-actions"><button class="ct-mini" data-ai="chatbot">💬 Ответить</button><button class="ct-mini" data-ai="moderate">🛡️ Проверить</button><button class="ct-mini" data-ai="copilot">🧠 Copilot</button></div><div class="ct-result" id="aiResult">Результат появится здесь.</div><div class="ct-actions"><button class="ct-mini" id="clipBtn">✂️ Отметить клип</button><button class="ct-mini" id="translateBtn">🌍 Перевести</button><button class="ct-mini" id="shortsBtn">📱 Сделать Shorts</button></div></aside>
</section>
<section class="ct-tools" id="tools"></section>
<div class="ct-log"><div class="ct-log-head"><span>Event log</span><span id="eventCount">0 событий</span></div><div class="ct-log-body" id="log"></div></div>
<div class="ct-note"><b>⚡ Нагрузка:</b> нет постоянного polling, WebSocket или фонового AI. Экранная демонстрация идёт напрямую между браузером и выбранным окном через стандартный браузерный API; AI вызывается только кнопкой/событием. Донаты и алерты сейчас имеют локальный тестовый режим, чтобы можно было проверить интерфейс без подключения платёжного провайдера.</div>
<div style="margin-top:14px;color:#6f7890;font-size:10px">Evruni Creator Tools · <?=htmlspecialchars((string)$u['name'],ENT_QUOTES,'UTF-8')?></div>
</main>
<script>
(()=>{
const API='/api/creator_tools.php';
const tools=[
 ['🎙️','Voice Cleaner','Шумоподавление и улучшение микрофона прямо в браузере.','mic'],
 ['💬','AI Chat Bot','Ответы зрителям и команды чата по событию.','chat'],
 ['🛡️','AI Moderator','Проверка нового сообщения без постоянного сканирования.','moderation'],
 ['🎨','Chat Overlay','Красивый чат поверх демонстрации/стрима.','overlay'],
 ['🔔','Smart Alerts','Подписки, рейды и донаты с тестовым режимом.','alerts'],
 ['🌍','Live Translator','Перевод выбранной реплики по запросу.','translator'],
 ['🔞','Content Censor','Blur + локальный фильтр чувствительных сцен.','censor'],
 ['✂️','Auto Clips','Момент отмечается; тяжёлая нарезка запускается отдельно.','clips'],
 ['🧠','Stream Copilot','Одна подсказка на одно событие, без постоянного наблюдения.','copilot'],
 ['📊','Stream Analytics','События и локальная статистика текущей сессии.','analytics'],
 ['📝','Stream Summary','AI-сводка после стрима одним запуском.','summary'],
 ['📱','Shorts Maker','HOOK + TITLE + CAPTION + HASHTAGS для выбранного момента.','shorts']
];
const $=s=>document.querySelector(s), logEl=$('#log'); let events=0, micStream=null, screenStream=null;
function log(s){events++;$('#eventCount').textContent=events+' событий';const d=document.createElement('div');d.textContent=new Date().toLocaleTimeString()+' · '+s;logEl.prepend(d)}
function render(){const wrap=$('#tools');wrap.innerHTML=tools.map(t=>`<article class="ct-card" data-tool="${t[3]}"><div class="ct-icon">${t[0]}</div><h3>${t[1]}</h3><p>${t[2]}</p><div class="ct-actions"><button class="ct-mini tool-action" data-action="${t[3]}">Запустить</button></div></article>`).join('')}
async function ai(action,text){if(!text){$('#aiResult').textContent='Сначала введи событие или сообщение.';return}$('#aiResult').textContent='AI обрабатывает событие…';log('AI → '+action);try{const r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,text})});const j=await r.json();if(!r.ok)throw new Error(j.error||'Ошибка');$('#aiResult').textContent=j.result||j.message||'Готово';log('AI ← '+action+' готово')}catch(e){$('#aiResult').textContent=e.message;log('Ошибка → '+action)}}
async function share(){if(screenStream){screenStream.getTracks().forEach(t=>t.stop());screenStream=null;$('#screen').classList.remove('demo');$('#screenVideo').srcObject=null;$('#shareBtn').textContent='Начать демонстрацию';log('Демонстрация остановлена');return}try{screenStream=await navigator.mediaDevices.getDisplayMedia({video:true,audio:false});$('#screenVideo').srcObject=screenStream;$('#screen').classList.add('demo');$('#shareBtn').textContent='Остановить демонстрацию';log('Демонстрация экрана запущена');screenStream.getVideoTracks()[0].addEventListener('ended',()=>share())}catch(e){log('Демонстрация отменена')}}
async function mic(){if(micStream){micStream.getTracks().forEach(t=>t.stop());micStream=null;log('Voice Cleaner остановлен');return}try{micStream=await navigator.mediaDevices.getUserMedia({audio:{noiseSuppression:true,echoCancellation:true,autoGainControl:true}});log('Voice Cleaner: микрофон очищается локально')}catch(e){log('Нет доступа к микрофону')}}
$('#shareBtn').onclick=share;$('#stopBtn').onclick=()=>{if(screenStream)share()};$('#blurBtn').onclick=()=>{$('#screen').classList.toggle('blurred');log('Content Censor: blur '+($('#screen').classList.contains('blurred')?'ON':'OFF'))};$('#overlayBtn').onclick=()=>{$('#screen').classList.toggle('chat-on');log('Chat Overlay переключён')};$('#alertBtn').onclick=()=>{const s=$('#screen');s.classList.add('alert');setTimeout(()=>s.classList.remove('alert'),4500);log('Тестовый донат +500 ₽')};$('#clipBtn').onclick=()=>{log('Auto Clips: момент отмечен');fetch(API,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'clip_note'})}).catch(()=>{})};$('#translateBtn').onclick=()=>ai('translate',$('#eventText').value+'\nTarget language: English');$('#shortsBtn').onclick=()=>ai('shorts',$('#eventText').value);document.querySelectorAll('[data-ai]').forEach(b=>b.onclick=()=>ai(b.dataset.ai,$('#eventText').value));
document.addEventListener('click',e=>{const b=e.target.closest('.tool-action');if(!b)return;const a=b.dataset.action; if(a==='mic')mic();else if(a==='overlay'){$('#overlayBtn').click()}else if(a==='alerts'){$('#alertBtn').click()}else if(a==='censor'){$('#blurBtn').click()}else if(a==='clips'){$('#clipBtn').click()}else if(a==='chat')ai('chatbot',$('#eventText').value);else if(a==='moderation')ai('moderate',$('#eventText').value);else if(a==='translator')$('#translateBtn').click();else if(a==='copilot')ai('copilot',$('#eventText').value);else if(a==='shorts')$('#shortsBtn').click();else if(a==='summary')ai('summary',$('#eventText').value);else if(a==='analytics')log('Analytics: текущая сессия '+events+' событий')});
render();log('Creator Tools готов');
})();
</script></body></html>
